const input = $json;
const required = ['run_id', 'tenant_id', 'job_id', 'clip_index', 'source_url', 'clip_start', 'clip_end'];
const missing = required.filter(k => input[k] === undefined || input[k] === null || input[k] === '');
if (missing.length > 0) {
  throw new Error('LOOM_DYNAMIC_CANDIDATE_INVALID: Missing required fields: ' + missing.join(', '));
}

return [{ json: {
  ...input,
  source_context: input.source_context || null,
  platform_targets: input.platform_targets || ['tiktok', 'instagram_reels', 'youtube_shorts', 'facebook_reels'],
  streamer_profile: input.streamer_profile || null
} }];

const input = $('Validate Dynamic Candidate Input').item.json;
const tr = $json;

let transcriptText = '';
if (Array.isArray(tr.captions) && tr.captions.length > 0) {
  transcriptText = tr.captions.map(c => (typeof c === 'string' ? c : (c.text || c.word || ''))).filter(Boolean).join(' ');
} else if (typeof tr.transcript === 'string') {
  transcriptText = tr.transcript;
} else if (typeof tr.text === 'string') {
  transcriptText = tr.text;
} else if (typeof tr === 'string') {
  transcriptText = tr;
}
transcriptText = transcriptText.trim();

// no_speech is AUTHORITATIVE (renderer metadata, carried as input.no_speech).
let noSpeech;
if (input.no_speech === true || input.no_speech === false) {
  noSpeech = input.no_speech;
} else {
  noSpeech = transcriptText.length === 0;
}

return [{ json: {
  schema_version: '1.0',
  run_id: input.run_id,
  tenant_id: input.tenant_id,
  clip_id: input.job_id + ':' + input.clip_index,
  source_id: input.job_id,
  job_id: input.job_id,
  candidate_clip_url: input.asset_url || input.source_url,
  clip_transcript: transcriptText,
  clip_duration_seconds: (input.clip_end != null && input.clip_start != null) ? (input.clip_end - input.clip_start) : (tr.durationSec || null),
  no_speech: noSpeech,
  existing_hook: input.clip_hook || null,
  openshorts_score: input.clip_score || null,
  proposed_shorts_title: input.clip_title || null,
  source_title: input.source_title || null,
  master_asset: input.master_asset || null,
  ready_file: input.ready_file || null,
  captions_expected: input.captions_expected === true,
  captions_applied: input.captions_applied === true,
  hook_expected: input.hook_expected === true,
  hook_applied: input.hook_applied === true,
  transcript_segment_count: input.transcript_segment_count || 0,
  render_version: input.render_version || null,
  source_context: input.source_context || null,
  platform_targets: input.platform_targets || ['tiktok', 'instagram_reels', 'youtube_shorts', 'facebook_reels'],
  streamer_profile: input.streamer_profile || null
} }];
